import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';

test('contains the intended deployment conflict', async () => {
  const config = await readFile(new URL('../config/staging.yaml', import.meta.url), 'utf8');
  const docs = await readFile(new URL('../docs/deployment.md', import.meta.url), 'utf8');
  assert.match(config, /staging-v2/);
  assert.match(config, /\/readyz/);
  assert.match(docs, /staging-v1/);
  assert.match(docs, /\/health/);
});
